    discord_error = "Gửi thất bại. Vui lòng thử lại.", network = "Lỗi mạng.",
    no_request = "Trình thực thi của bạn không thể gửi yêu cầu.", bad_response = "Máy chủ trả về phản hồi không mong đợi.",
